// Code generated by backend/tools/gen-modelsetups from config/presets. DO NOT EDIT.

package ai

// stockPresets are the committed presets, by file name, as their files read.
var stockPresets = map[string]string{
	"anthropic_cloud.yaml":         "# yaml-language-server: $schema=../margince.schema.json\n# Model setup: Anthropic Claude\n# config/presets/anthropic_cloud.yaml — the chat tiers on Claude, embeddings on Gemini.\n#\n# NOT YET MEASURED: no certification record exists for this setup, so no task is\n# graded on it and none of its answers is known to be good enough. Certify it\n# with the command below; its grades then appear in docs/reference/ai-certification.md\n# under this file's name. Until then, do not bind this preset to a workspace whose\n# confidentiality decisions matter.\n#\n# It pairs the tiers the way gemini_cloud.yaml does: the small, cheap model leads\n# the short-answer and cheap tasks, and the larger one leads premium and frontier.\n# So a record of one setup reads against the other tier by tier.\n#\n#     make e2e-ai ROUTING=config/presets/anthropic_cloud.yaml \\\n#       JUDGE=gemini:gemini-3.1-flash-lite\n#\n# The judge is a Gemini model on purpose: the default judge (Claude, through\n# `claude -p`) refuses a Claude candidate, and the run never takes a judge from\n# the routing. One judge grades the whole sweep.\n#\n# Needs ANTHROPIC_API_KEY for the tiers and GEMINI_API_KEY for the embeddings,\n# because Anthropic serves no embedding model. Not loaded automatically — see\n# README.md.\nversion: 1\n\nseeds:\n  ai_routing:\n    # cloud_frontier: the Anthropic API states no EU processing region, so\n    # nothing here keeps text in the EU.\n    profile: cloud_frontier     # eu_hosted | sovereign | cloud_frontier\n    tiers:\n      local_small: { provider: anthropic, model: claude-haiku-5-5 }\n      cheap_cloud: { provider: anthropic, model: claude-haiku-5-5 }\n      premium:     { provider: anthropic, model: claude-sonnet-5-5 }\n      frontier:    { provider: anthropic, model: claude-sonnet-5-5 }\n    # No thinking_level: that field is Gemini's. The Anthropic adapter picks its\n    # own effort per request, and a tier cannot set one.\n    #\n    # The same three tasks gemini_cloud.yaml walks premium first, so the two\n    # setups are compared on the same ladders.\n    task_ladders:\n      agent_loop: [premium, cheap_cloud]\n      nl_search: [premium, cheap_cloud]\n      voice_build: [premium, cheap_cloud]\n    # Anthropic has no embedding model, so the embed lane rides Gemini, as in\n    # gemini_cloud.yaml. 1536 is one of gemini-embedding-001's output widths.\n    embeddings:\n      provider: gemini\n      model: gemini-embedding-001\n      dimensions: 1536\n",
	"consumer_class_brokered.yaml": "# yaml-language-server: $schema=../margince.schema.json\n# Model setup: Gemma 4 you could run yourself, through OpenRouter\n# config/presets/consumer_class_brokered.yaml — weights a customer could host on\n# their own consumer hardware, served through the broker so we can measure them\n# before anybody buys a GPU.\n#\n# WHAT THIS PRESET IS NOT CERTIFIED FOR: it binds a model to every task, and the\n# certification records do not grade every one of those bindings as certified.\n# Which tasks, and how badly, is in docs/reference/ai-certification.md under\n# this file's name. Read it before binding this preset to a workspace whose\n# confidentiality decisions matter: a task graded `supported_degraded` or\n# `not_supported` answers wrongly often enough to have been measured doing so.\n#\n# No task list here on purpose. The bands move when a prompt is fixed or the\n# corpus grows, and a list in this comment would read as true long after it\n# stopped being.\n#\n# This preset answers ONE question: is the open-weight class that fits on a\n# 24GB card good enough to carry Margince's tasks? It is deliberately NOT the\n# sovereign binding. Every call here leaves the building — the models are the\n# ones a customer could run, the SERVING is DeepInfra's and Parasail's. That is\n# why `profile: cloud_frontier` below, and it is not a downgrade of ambition: the\n# sovereign Ollama binding of the same weights is a DIFFERENT measurement and\n# must file under a different profile, or the two records collide on one\n# filename (provider_model_envclass.json) and the honest local number\n# overwrites, or is overwritten by, this proxy.\n#\n# So: certify here first, cheaply, to find out which weights are worth the\n# hardware time. Then rebind the survivors to `provider: ollama` on loopback\n# with `profile: sovereign` and pay for the real run.\n#\n#     make e2e-ai ROUTING=config/presets/consumer_class_brokered.yaml \\\n#       JUDGE=openai_compatible:mistralai/mistral-large-2512 \\\n#       JUDGE_BASE_URL=https://openrouter.ai/api\n#\n# The judge is NOT from this family and NOT resolved from this file. Every rung\n# below is Gemma 4, and cert_judge leads at premium — so a judge taken from the\n# routing would grade Gemma 4 with Gemma 4 on every premium-led task, which is\n# certified by construction. mistral-large is named because it is the strongest\n# thing the same one credential already reaches.\n#\n# THE FAMILY, AND THE A/B. Gemma 4 is what this file binds. The other candidate\n# worth a run is Qwen — as of 2026-09 the consumer-local field's pick for a\n# single 24GB card is the dense `qwen/qwen3.8-27b` (262K window, tools and\n# structured output on 14 of its 16 endpoints). To A/B it, copy this file and\n# swap the three model ids; do NOT edit this one in place, because a record is\n# filed under the model it measured and the comparison is the point.\n#\n# WHAT WILL FAIL, AND WHY IT IS NOT THIS FILE'S BUG. document_extract sends a\n# PDF, and the OpenAI-compatible adapter's wire has image parts and no document\n# part (internal/modules/ai/carriage.go) — so that one task fails under any\n# openai_compatible binding, loudly. The Ollama wire is the same shape, so the\n# eventual sovereign run cannot serve it either: for a consumer-hosted\n# deployment, document_extract needs a rung on a provider whose wire carries\n# PDFs. Worth knowing BEFORE the hardware is bought, which is another reason to\n# run the cheap proxy first.\n#\n# Not loaded automatically — see README.md.\nversion: 1\n\nseeds:\n  ai_routing:\n    # The profile is a three-value enum, and `cloud_frontier` is the one that\n    # fits: it means BYOK CLOUD (config/margince.schema.json), which is exactly\n    # this file — our own broker credential reaching a third party's inference\n    # host. It does NOT mean \"a frontier-class model\", and nothing here is one.\n    #\n    # The other two are wrong for different reasons. `sovereign` is zero egress\n    # and is enforced, not labelled: it refuses a cloud provider outright, and\n    # it is the profile the eventual Ollama binding of these same weights will\n    # carry. `eu_hosted` claims partner EU inference, which this file cannot\n    # promise — the endpoints it reaches at fp8 are DeepInfra's and Parasail's,\n    # pinned by precision and not by region.\n    profile: cloud_frontier\n    providers:\n      openai_compatible:\n        base_url: https://openrouter.ai/api\n    tiers:\n      # Every rung is sized to a hardware class an operator can check against\n      # their own box. The Q4 footprints are for the eventual Ollama run; they\n      # are stated here because they are the reason these three ids and not\n      # three larger ones.\n      #\n      # local_small leads 7 tasks — capture_classify, the two capture verdicts,\n      # owed_verdict, request_settlement, tag_suggest, enrich. All short answers under a JSON\n      # schema, so schema adherence is the whole job and size buys little.\n      #\n      # 26b-a4b is the MoE: 26B of weights, ~4B active per token. That is the\n      # variant that makes this tier honest on a LAPTOP — it is the 16GB-class\n      # rung, fast on hardware that would crawl under a dense 26B.\n      local_small:\n        provider: openai_compatible\n        model: google/gemma-4-26b-a4b-it   # ~16GB at Q4; MoE, ~4B active\n        # An anchor, reused by every tier below: the serving preferences are one\n        # decision about what a consumer box looks like, so they are written\n        # once. Copy the WHOLE seeds block — lifting a single tier out of this\n        # file leaves an alias with nothing to point at.\n        routing: &consumer_serving\n          provider:\n            # sort: throughput for the reason the product default has it — it is\n            # the lever that collapses the broker's latency tail\n            # (docs/explanation/openrouter-upstream-choice.md).\n            sort: throughput\n            # fp8, NOT the product default's [fp16, bf16]. The question this file\n            # asks is what a consumer box produces, and a consumer box does not\n            # run bf16 — it runs a 4- to 8-bit quant. fp8 is the closest precision\n            # served for BOTH ids below with tools and structured output intact;\n            # fp4 exists for the 31B and not for the MoE, so pinning it would\n            # leave this tier with no endpoint at all. It is one step from what an\n            # operator will really run, and the direction of the error is known:\n            # the sovereign run at Q4 should score at or below this.\n            #\n            # Pinning ONE level rather than listing several is what makes repeats\n            # comparable — two answers from one model id at fp8 and at bf16 are\n            # two models for every purpose except billing.\n            quantizations: [fp8]\n            # Keeps a structured-output or tool request away from a host that\n            # cannot honour it. It matters more here than on a frontier binding:\n            # the fp8 endpoints for these ids are a short list, and one of them\n            # serves no tools.\n            require_parameters: true\n      # cheap_cloud leads 17 tasks, and one of them is agent_loop — a cumulative\n      # reason-act window fed 7 tools. TOOL CALLING is therefore this tier's\n      # hard requirement, not a nicety, and it is the thing to watch in the\n      # results: it is where an open-weight rung most often turns out not to\n      # carry the product.\n      cheap_cloud:\n        provider: openai_compatible\n        model: google/gemma-4-31b-it       # ~19GB at Q4; one 24GB card / 32GB Mac\n        routing: *consumer_serving\n      # premium leads 6 tasks and is the rung that decides whether any of this\n      # works. corpus_ask and site_extract drop every claim whose quote is not\n      # VERBATIM in the retrieved passage — that discipline, not fluency, is\n      # what small open weights are worst at, and no fallback rung exists to\n      # catch them (both are premium-only by contract).\n      #\n      # Bound to the same 31B as cheap_cloud on purpose: 31B dense at Q4 IS the\n      # ceiling of \"consumer hardware\", so a premium rung above it would be a\n      # model this preset's whole premise says the customer cannot run. The\n      # answer to \"premium is too weak\" is not a bigger local model, it is that\n      # those tasks need a cloud rung.\n      premium:\n        provider: openai_compatible\n        model: google/gemma-4-31b-it\n        routing: *consumer_serving\n      # No ladder leads at frontier (backend/api/ai-tasks.yaml), so this is here\n      # only so a task reaching for the top rung finds something bound. It is\n      # the same 31B for the reason premium is: there is nothing above it that a\n      # consumer box runs.\n      frontier:\n        provider: openai_compatible\n        model: google/gemma-4-31b-it\n        routing: *consumer_serving\n    # The embed lane is the one place this preset is NOT consumer-class, and it\n    # is the broker's fault rather than a choice: it fronts no open-weight\n    # embedding model worth binding. mistral-embed stands in.\n    #\n    # 1024 is mistral-embed's width AND bge-m3's — the model the sovereign\n    # Ollama binding will use — so a later move onto local weights does not\n    # change the COLUMN. It does not make the vectors comparable: two models\n    # write different spaces at the same width, and querying bge-m3 against\n    # stored mistral-embed vectors returns confident nonsense. Changing the\n    # embedding model means re-embedding everything already filed, whatever the\n    # width says. Equal width saves a migration, not a re-embed.\n    #\n    # No serving preferences: the parser refuses them on the embed lane, since\n    # a single forward pass has no latency tail to bound.\n    embeddings:\n      provider: openai_compatible\n      model: mistralai/mistral-embed-2312\n      dimensions: 1024\n",
	"gemini_cloud.yaml":            "# yaml-language-server: $schema=../margince.schema.json\n# Model setup: Google Gemini\n# config/presets/gemini_cloud.yaml — every lane on Gemini, one credential.\n#\n# WHAT THIS PRESET IS NOT CERTIFIED FOR: it binds a model to every task, and the\n# certification records do not grade every one of those bindings as certified.\n# Which tasks, and how badly, is in docs/reference/ai-certification.md under\n# this file's name. Read it before binding this preset to a workspace whose\n# confidentiality decisions matter: a task graded `supported_degraded` or\n# `not_supported` answers wrongly often enough to have been measured doing so.\n#\n# No task list here on purpose. The bands move when a prompt is fixed or the\n# corpus grows, and a list in this comment would read as true long after it\n# stopped being.\n#\n# The binding a dev stack bootstraps with, lifted out of margince.dev.yaml so it\n# can be named, diffed and reused. Copy the `seeds` block into your own\n# config/margince.yaml, or point a certification run at this file:\n#\n#     make e2e-ai ROUTING=config/presets/gemini_cloud.yaml\n#\n# The default judge (Claude, through `claude -p`) is off this preset, so one\n# judge grades it all.\n#\n# Needs GEMINI_API_KEY and nothing else. Not loaded automatically — see README.md.\nversion: 1\n\nseeds:\n  ai_routing:\n    # cloud_frontier, not eu_hosted: the Gemini Developer API states no EU\n    # processing region, so nothing here keeps text in the EU.\n    profile: cloud_frontier     # eu_hosted | sovereign | cloud_frontier\n    tiers:\n      local_small: { provider: gemini, model: gemini-3.1-flash-lite }\n      cheap_cloud: { provider: gemini, model: gemini-3.1-flash-lite }\n      # thinking_level low: a prose site sends no schema, so without it a Flash\n      # model thinks at its own default — measured on gemini-3.6-flash at 4–8k\n      # reasoning tokens against the ~8k output cap, which cut one call in eight short.\n      premium:     { provider: gemini, model: gemini-3.8-flash, thinking_level: low }\n      frontier:    { provider: gemini, model: gemini-3.8-flash, thinking_level: low }\n    # Three tasks answer on premium first, where Flash certifies and\n    # Flash-Lite does not: the scheduled agents (on Flash-Lite a line planted\n    # in a CRM record reached their findings), search planning and the voice\n    # profile. Every agent step, search plan and voice build pays premium\n    # tokens. Reply drafts stay on Flash-Lite first: there it is usable with\n    # care, and on Flash its account drafts fail two privacy cases.\n    task_ladders:\n      agent_loop: [premium, cheap_cloud]\n      nl_search: [premium, cheap_cloud]\n      voice_build: [premium, cheap_cloud]\n    # The embed lane rides the SAME provider as the tiers above, so this preset\n    # needs one credential rather than two.\n    #\n    # 1536 is one of gemini-embedding-001's supported output widths; on the\n    # gemini provider the number is a request for that width. Why, once:\n    # docs/how-to/connect-a-cloud-model-provider.md §3.\n    embeddings:\n      provider: gemini\n      model: gemini-embedding-001\n      dimensions: 1536\n    # The decision model, opt-in: uncomment ONE block to have a decision site\n    # asked a decision model before its ladder. Through OpenRouter,\n    # JEV_COMPATIBLE_API_KEY takes your OpenRouter key:\n    # decisions:\n    #   provider: jev_compatible\n    #   model: typesafe/jev-1.13\n    #   base_url: https://openrouter.ai/api/alpha/decisions\n    # Or TypeSafe's own API, keyed by TYPESAFE_API_KEY:\n    # decisions:\n    #   provider: jev\n    #   model: jev-1.13.0\n    # Or Google's Decisions API, on the GEMINI_API_KEY this preset already\n    # needs, certified for all three decision sites (Developer API only, no\n    # EU hosting):\n    # decisions:\n    #   provider: gemini_decision\n    #   model: gemini-decision-1\n",
	"gemini_vertex_eu.yaml":        "# yaml-language-server: $schema=../margince.schema.json\n# Model setup: Google Gemini in the EU, through Vertex AI\n# config/presets/gemini_vertex_eu.yaml — every lane on Gemini served by Vertex AI\n# at an EU location, under eu_hosted.\n#\n# WHAT THIS PRESET IS NOT CERTIFIED FOR: it binds a model to every task, and the\n# certification records do not grade every one of those bindings as certified.\n# Which tasks, and how badly, is in docs/reference/ai-certification.md under\n# this file's name. Read it before binding this preset to a workspace whose\n# confidentiality decisions matter: a task graded `supported_degraded` or\n# `not_supported` answers wrongly often enough to have been measured doing so.\n#\n# No task list here on purpose. The bands move when a prompt is fixed or the\n# corpus grows, and a list in this comment would read as true long after it\n# stopped being.\n#\n# What it guarantees: Google processes every prompt, and every text embedded,\n# in EU member states. The chat tiers use the `eu` multi-region; the embeddings\n# lane uses europe-west4, because `eu` serves no embedding model. eu_hosted\n# refuses London (europe-west2), Zürich (europe-west6), `global` and `us` at save.\n# It covers AI inference only — docs/how-to/connect-a-cloud-model-provider.md §5.\n#\n# Needs one service-account JSON key, from GEMINI_VERTEX_SA_JSON or Settings →\n# AI → AI models → Providers, on an account holding roles/aiplatform.user in a\n# project with the Vertex AI API enabled. Not loaded automatically — see\n# README.md.\nversion: 1\n\nseeds:\n  ai_routing:\n    profile: eu_hosted          # eu_hosted | sovereign | cloud_frontier\n    # Where Google processes every chat tier's call, written once.\n    providers:\n      gemini_vertex:\n        location: eu\n    # gemini_cloud.yaml's Flash and Flash-Lite at its thinking levels, so its\n    # certification records grade these rungs (aicert.MeasuredAs). Vertex serves\n    # no Pro model in the EU, so frontier takes premium's Flash.\n    tiers:\n      local_small: { provider: gemini_vertex, model: gemini-3.1-flash-lite }\n      cheap_cloud: { provider: gemini_vertex, model: gemini-3.1-flash-lite }\n      premium:     { provider: gemini_vertex, model: gemini-3.8-flash, thinking_level: low }\n      frontier:    { provider: gemini_vertex, model: gemini-3.8-flash, thinking_level: low }\n    # Three tasks answer on premium first, where Flash certifies and\n    # Flash-Lite does not: the scheduled agents (on Flash-Lite a line planted\n    # in a CRM record reached their findings), search planning and the voice\n    # profile. Every agent step, search plan and voice build pays premium\n    # tokens. Reply drafts stay on Flash-Lite first: there it is usable with\n    # care, and on Flash its account drafts fail two privacy cases.\n    task_ladders:\n      agent_loop: [premium, cheap_cloud]\n      nl_search: [premium, cheap_cloud]\n      voice_build: [premium, cheap_cloud]\n    # The width is asked of the model as outputDimensionality, as on gemini.\n    # The embedder keeps a location of its own, which overrides the provider's\n    # for this lane alone.\n    embeddings:\n      provider: gemini_vertex\n      location: europe-west4\n      model: gemini-embedding-001\n      dimensions: 1536\n",
	"gemma4_local_ollama.yaml":     "# yaml-language-server: $schema=../margince.schema.json\n# Model setup: Gemma 4 on your own server, through Ollama\n# config/presets/gemma4_local_ollama.yaml — Gemma 4 on the operator's own box,\n# through Ollama on loopback. Zero egress.\n#\n# WHAT THIS PRESET IS NOT CERTIFIED FOR: it binds a model to every task, and the\n# certification records do not grade every one of those bindings as certified.\n# Which tasks, and how badly, is in docs/reference/ai-certification.md under\n# this file's name. Read it before binding this preset to a workspace whose\n# confidentiality decisions matter: a task graded `supported_degraded` or\n# `not_supported` answers wrongly often enough to have been measured doing so.\n#\n# No task list here on purpose. The bands move when a prompt is fixed or the\n# corpus grows, and a list in this comment would read as true long after it\n# stopped being.\n#\n# This is the SOVEREIGN counterpart of consumer_class_brokered.yaml: the same\n# open-weight family, but served here instead of brokered, so it files under a\n# different profile and the two records never share a filename. The brokered\n# preset answers \"which weights are worth buying hardware for\"; this one answers\n# \"what does the hardware you bought actually do\".\n#\n#     ollama pull gemma4:12b && ollama pull bge-m3\n#     make e2e-ai ROUTING=config/presets/gemma4_local_ollama.yaml\n#\n# The judge is NOT resolved from this file — every tier below is Gemma 4, and a\n# judge equal to the candidate grades itself — so the default cloud judge\n# grades it: a certification run holds only the candidate to `sovereign`. A\n# local judge (JUDGE=ollama:gpt-oss:20b) fits beside a 12b on a 24GB machine\n# only by unloading it between calls, and its reloads then land in the\n# recorded latency; measure serving speed with a direct call, not a record.\n#\n# NOT YET MEASURED: no record is committed for this binding, so every task\n# reads \"not measured\" on the certification page. The last run, on older\n# weights, is in docs/explanation/ollama-self-hosting.md section 4.\n#\n# WHY 12b ON EVERY TIER. Sized for a 24GB Apple-silicon machine, the smallest\n# this preset is meant to run on, with Ollama 0.34 (its server log reports\n# about 17.8GiB of that memory usable by the GPU, and that budget picks the id):\n#\n#   e4b   27 tok/s   fast, but 5 of 15 capture_classify runs passed: it mangles\n#                    message ids and answers a reply for mail we sent. Not a\n#                    tier this product can lean on.\n#   12b   12 tok/s   8.3GB resident at a 12K window, all on the GPU. Passed\n#                    every capture_classify run.\n#   26b   10 tok/s   MoE, ~4B active per token, but 18GB of weights: 65% of it\n#                    ran on the CPU at the same window and a load took 21s.\n#                    Bind `premium` and `frontier` to it on a machine with\n#                    32GB or more; on 24GB it is slower than 12b, not better.\n#\n# The 31B is absent: it does not fit a 24GB machine at 4 bits.\n#\n# `document_extract` cannot be served: it sends a PDF and the Ollama wire carries\n# images only (internal/modules/ai/carriage.go). That task fails under this\n# preset by design; see README.md.\n#\n# Not loaded automatically — see README.md.\nversion: 1\n\nseeds:\n  ai_routing:\n    # sovereign is enforced, not labelled: it refuses any cloud provider, and it\n    # refuses an Ollama base_url that is not loopback or a private range. Omitting\n    # base_url resolves to http://localhost:11434, which passes.\n    profile: sovereign\n    tiers:\n      local_small: { provider: ollama, model: \"gemma4:12b\" }\n      cheap_cloud: { provider: ollama, model: \"gemma4:12b\" }\n      premium:     { provider: ollama, model: \"gemma4:12b\" }\n      frontier:    { provider: ollama, model: \"gemma4:12b\" }\n    # bge-m3 is 1024-wide, the same column width the brokered preset's\n    # mistral-embed stand-in uses, so moving between the two changes no column.\n    # It does not make the vectors comparable — re-embed on any model change.\n    embeddings:\n      provider: ollama\n      model: bge-m3\n      dimensions: 1024\n",
	"openrouter_cloud.yaml":        "# yaml-language-server: $schema=../margince.schema.json\n# Model setup: Open models from OpenAI and Mistral, through OpenRouter\n# config/presets/openrouter_cloud.yaml — every lane through the OpenRouter broker.\n#\n# WHAT THIS PRESET IS NOT CERTIFIED FOR: it binds a model to every task, and the\n# certification records do not grade every one of those bindings as certified.\n# Which tasks, and how badly, is in docs/reference/ai-certification.md under\n# this file's name. Read it before binding this preset to a workspace whose\n# confidentiality decisions matter: a task graded `supported_degraded` or\n# `not_supported` answers wrongly often enough to have been measured doing so.\n#\n# No task list here on purpose. The bands move when a prompt is fixed or the\n# corpus grows, and a list in this comment would read as true long after it\n# stopped being.\n#\n# One credential (OPENAI_COMPATIBLE_API_KEY) reaches many vendors, which is the\n# reason to use a broker and also the reason this file spends most of its lines\n# on `routing:`. A broker fronts MANY inference hosts per model — gpt-oss-120b\n# had 21 when this was written — and its own default picks among them weighted by\n# the inverse square of price. One model id then arrives at fp4 on one call and\n# bf16 on the next, with latency to match.\n#\n# Not loaded automatically — see README.md. Copy the `seeds` block into your own\n# config/margince.yaml, or:\n#\n#     make e2e-ai ROUTING=config/presets/openrouter_cloud.yaml TASK=<task>\n#\n# The default judge, claude_cli:claude-sonnet-5-5, grades every task but\n# signal_extract, whose frontier rung binds a Claude model the runner will not\n# let a Claude judge grade: run that task alone with\n# JUDGE=gemini:gemini-3.1-flash-lite (so GEMINI_API_KEY too).\n#\n# The measurements behind every `routing:` value here, and what was tried and\n# rejected: docs/explanation/openrouter-upstream-choice.md.\nversion: 1\n\nseeds:\n  ai_routing:\n    # cloud_frontier, not eu_hosted: no tier here pins a region, so the broker\n    # serves each one from wherever its routing lands. openrouter_cloud_eu.yaml\n    # is the EU-pinned one.\n    profile: cloud_frontier     # eu_hosted | sovereign | cloud_frontier\n    # A provider's host is written once, here, and every lane on it reads it.\n    # base_url is the host root with NO version segment — the adapter appends\n    # /v1. openai_compatible fails closed without one.\n    providers:\n      openai_compatible:\n        base_url: https://openrouter.ai/api\n    tiers:\n      # Every tier below omits `routing:`, which means it inherits the product\n      # default: sort: throughput, quantizations: [fp16, bf16],\n      # require_parameters: true — reliability over price. Write `routing: {}` on\n      # a tier to opt out and take the broker's own price-weighted routing\n      # instead; write the block out to say something else.\n      local_small:\n        provider: openai_compatible\n        model: openai/gpt-oss-120b\n      cheap_cloud:\n        provider: openai_compatible\n        model: openai/gpt-oss-120b\n      premium:\n        provider: openai_compatible\n        model: mistralai/mistral-medium-3-5\n        # `{}` is load-bearing, not decoration: the inherited default filters\n        # on `quantizations: [fp16, bf16]`, and Mistral's first-party endpoints\n        # declare their precision as `unknown`. Inheriting it empties the\n        # candidate set and the broker answers every premium call with \"No\n        # endpoints found for the request with quantization: fp16,bf16\".\n        #\n        # What the opt-out gives up costs nothing here. Both endpoints are\n        # first-party Mistral, so there is no serving lottery to lose and\n        # nothing for a sort to choose between.\n        #\n        # This tier named mistral-large-2512 until the broker stopped serving it\n        # outside its batch endpoint. Nothing in this tree changed and every\n        # premium task on this preset began failing with \"No endpoints found\" —\n        # a model on somebody else's catalogue can be withdrawn under a\n        # committed config, so a preset is worth re-reaching before it is\n        # trusted.\n        routing: {}\n      frontier:\n        provider: openai_compatible\n        model: anthropic/claude-sonnet-4.6\n        routing:\n          provider:\n            # A frontier answer is worth waiting for, so this tier does not sort\n            # for speed. What it does refuse is a quantized serving of a model\n            # bound for its quality.\n            quantizations: [fp16, bf16, fp32]\n            require_parameters: true\n    # KNOWN GAP: this preset cannot serve document_extract, which sends a PDF.\n    # On the OpenAI-compatible wire the carriage is the operator's `input:`\n    # declaration, and that vocabulary is text and image only — there is no way\n    # to declare application/pdf, so the adapter refuses the attachment rather\n    # than dropping it. A full certification run under this preset therefore\n    # fails that one task, loudly and correctly. Bind document_extract's tier to\n    # a provider whose wire carries PDFs (gemini does, and is what the committed\n    # record for that task uses) if a deployment needs it.\n    #\n    # The embed lane takes no serving preferences — the parser refuses them. An\n    # embedding is a single forward pass, so it has no latency tail to bound, and\n    # no embed model is served at fp4-versus-bf16 stakes.\n    embeddings:\n      provider: openai_compatible\n      model: mistralai/mistral-embed-2312\n      dimensions: 1024\n    # The decision model, opt-in: uncomment to have a decision site asked\n    # OpenRouter's Jev endpoint before its ladder. JEV_COMPATIBLE_API_KEY takes\n    # your OpenRouter key (the same one as OPENAI_COMPATIBLE_API_KEY above).\n    # A lane's base_url is lifted onto its provider when the provider names\n    # none, so this block works uncommented as one step.\n    # decisions:\n    #   provider: jev_compatible\n    #   model: typesafe/jev-1.13\n    #   base_url: https://openrouter.ai/api/alpha/decisions\n",
	"openrouter_cloud_eu.yaml":     "# yaml-language-server: $schema=../margince.schema.json\n# Model setup: Mistral models in the EU, through OpenRouter\n# config/presets/openrouter_cloud_eu.yaml — every lane, chat and embeddings, on\n# Mistral's EU endpoint.\n#\n# WHAT THIS PRESET IS NOT CERTIFIED FOR: it binds a model to every task, and the\n# certification records do not grade every one of those bindings as certified.\n# Which tasks, and how badly, is in docs/reference/ai-certification.md under\n# this file's name. Read it before binding this preset to a workspace whose\n# confidentiality decisions matter: a task graded `supported_degraded` or\n# `not_supported` answers wrongly often enough to have been measured doing so.\n#\n# No task list here on purpose. The bands move when a prompt is fixed or the\n# corpus grows, and a list in this comment would read as true long after it\n# stopped being.\n#\n# Every lane here is served under an EU-region endpoint in `only:`, which the\n# provider's `upstream` names once for all of them. Without it the broker serves a model from any\n# region — including a model with no EU endpoint at all, which it then serves\n# from somewhere else without failing.\n#\n# The sibling openrouter_cloud.yaml picks the best model per tier and lets the\n# broker choose a host. This file inverts that: the host is fixed first, and the\n# tiers get whichever Mistral weights that host serves. `only: [mistral/eu]` is\n# OpenRouter's EU-region endpoint for Mistral SAS — not the base `mistral` slug,\n# which matches every region and so is a vendor preference rather than a\n# location one.\n#\n# `premium` names mistralai/mistral-medium-3-5, Mistral's flagship, served from\n# the EU endpoint since the broker added `mistral/eu` for it (read 2026-09-29).\n# `frontier` names mistral-small-2603 rather than the flagship a second time. No\n# shipped task leads at frontier, so it is only ever premium's fallback, and a\n# fallback to the same model is the same upstream endpoint: one 429 there would\n# burn both rungs. A different model is a different capacity pool.\n#\n# That 429 is rarely ours. Without a key of its own the broker serves Mistral\n# from ITS key, one capacity pool shared by every account on it. Each model\n# here has exactly one EU endpoint, so the pool is an account setting: attach a\n# Mistral API key to the OpenRouter account (its \"bring your own key\"\n# integration) and calls draw on that key's limits. A deployment on this preset\n# should, before it relies on premium or frontier.\n#\n# `cheap_cloud` deliberately does NOT join them — see the note on that tier.\n#\n# The EU endpoint also bills about 10% above the default one across every model\n# below. The seeded price sheet carries the DEFAULT-endpoint number, because it\n# is keyed by model id and both presets bind the same ids; a deployment running\n# this preset and reconciling against an invoice edits ai_model_rate.\n#\n# Not loaded automatically — see README.md. Copy the `seeds` block into your own\n# config/margince.yaml, or:\n#\n#     make e2e-ai ROUTING=config/presets/openrouter_cloud_eu.yaml\n#\n# The default judge (Claude, through `claude -p`) is bound on no tier here, so\n# it grades every task this preset certifies.\n#\n# On the `routing:` block's fields and the measurements behind them:\n# docs/explanation/openrouter-upstream-choice.md.\nversion: 1\n\nseeds:\n  ai_routing:\n    profile: eu_hosted\n    # The pin is the provider's: every lane on the broker, embeddings included,\n    # is served from an EU-region host or not at all. It reads every document\n    # the chat tiers do, so a lane left to the broker's choice of region would\n    # be the one place the preset's promise did not reach.\n    providers:\n      openai_compatible:\n        base_url: https://openrouter.ai/api\n        upstream:\n          provider:\n            only: [mistral/eu]\n    tiers:\n      # Every tier writes `routing:` out rather than inheriting the product\n      # default, and the reason is not style. That default filters on\n      # `quantizations: [fp16, bf16]`, and Mistral's first-party endpoints\n      # declare their precision as `unknown` — so inheriting it would leave the\n      # candidate set EMPTY and every call would fail to route. A tier here\n      # says nothing about precision; the pin comes from the provider.\n      #\n      # No `sort:` either: the pin leaves exactly one endpoint, so an ordering\n      # preference would have nothing to order and would disable the broker's\n      # load balancing to achieve it.\n      local_small:\n        provider: openai_compatible\n        model: mistralai/ministral-8b-2512\n        routing:\n          provider:\n            require_parameters: true\n      # A DIFFERENT model from the rung above it, and that is the point rather\n      # than an accident of shopping. mistral-small-2603 answers better here —\n      # ministral-14b breaks a multi-paragraph email body across JSON string\n      # boundaries, which is why draft_reply is not certified on this preset —\n      # and binding both rungs to the better model was tried and withdrawn.\n      #\n      # Two rungs naming one model is not a ladder. A task whose first rung is\n      # this one falls through to `premium` on failure, and if both name the\n      # same binding the fallback reaches the same endpoint: one upstream 429\n      # then burns the whole ladder, because the router walks each rung exactly\n      # once. Measured under the collapsed shape, 8 of 12 tasks on\n      # mistral-small-2603 failed that way while all 5 on ministral-8b passed.\n      cheap_cloud:\n        provider: openai_compatible\n        model: mistralai/ministral-14b-2512\n        routing:\n          provider:\n            require_parameters: true\n      premium:\n        provider: openai_compatible\n        model: mistralai/mistral-medium-3-5\n        routing:\n          provider:\n            require_parameters: true\n      frontier:\n        provider: openai_compatible\n        model: mistralai/mistral-small-2603\n        routing:\n          provider:\n            require_parameters: true\n    # KNOWN GAP: like its sibling, this preset cannot serve document_extract.\n    # That task sends a PDF, and the OpenAI-compatible wire's declarable\n    # carriage is text and image only — the adapter refuses the attachment\n    # rather than dropping it, so a full certification run fails that one task\n    # loudly and correctly.\n    embeddings:\n      provider: openai_compatible\n      model: mistralai/mistral-embed-2312\n      dimensions: 1024\n    # No `decisions:` lane: neither an OpenRouter nor a TypeSafe decision\n    # endpoint can be pinned to an EU host.\n",
	"openrouter_openai.yaml":       "# yaml-language-server: $schema=../margince.schema.json\n# Model setup: OpenAI GPT-6, through OpenRouter\n# config/presets/openrouter_openai.yaml — every lane on OpenAI's GPT-6 family,\n# reached through the OpenRouter broker.\n#\n# WHAT THIS PRESET IS NOT CERTIFIED FOR: it binds a model to every task, and the\n# certification records do not grade every one of those bindings as certified.\n# Which tasks, and how badly, is in docs/reference/ai-certification.md under\n# this file's name. Read it before binding this preset to a workspace whose\n# confidentiality decisions matter: a task graded `supported_degraded` or\n# `not_supported` answers wrongly often enough to have been measured doing so.\n#\n# No task list here on purpose. The bands move when a prompt is fixed or the\n# corpus grows, and a list in this comment would read as true long after it\n# stopped being.\n#\n# One credential (OPENAI_COMPATIBLE_API_KEY), the same one the other broker\n# presets use. The models are first-party OpenAI endpoints on the broker, so\n# there is no serving lottery for `routing:` to bound.\n#\n# Not loaded automatically — see README.md. Copy the `seeds` block into your own\n# config/margince.yaml, or:\n#\n#     make e2e-ai ROUTING=config/presets/openrouter_openai.yaml\n#\n# The default judge is a Claude model through `claude -p`, so nothing bound here\n# grades itself.\nversion: 1\n\nseeds:\n  ai_routing:\n    # cloud_frontier, not eu_hosted: no tier pins a region.\n    profile: cloud_frontier     # eu_hosted | sovereign | cloud_frontier\n    providers:\n      openai_compatible:\n        base_url: https://openrouter.ai/api\n    tiers:\n      # Every tier opts out of the inherited routing with `routing: {}`. The\n      # product default filters on `quantizations: [fp16, bf16]`, and OpenAI\n      # declares no precision for a hosted model, so inheriting it empties the\n      # candidate set and the broker answers \"No endpoints found for the\n      # request with quantization: fp16,bf16\". Nothing is given up: one vendor\n      # serves each model.\n      local_small:\n        provider: openai_compatible\n        model: openai/gpt-6-luna\n        routing: {}\n      cheap_cloud:\n        provider: openai_compatible\n        model: openai/gpt-6-luna\n        routing: {}\n      premium:\n        provider: openai_compatible\n        model: openai/gpt-6-sol\n        routing: {}\n      frontier:\n        provider: openai_compatible\n        model: openai/gpt-6.1-sol\n        routing: {}\n    # KNOWN GAP: this preset cannot serve document_extract, which sends a PDF.\n    # The models take file input, but the OpenAI-compatible wire here declares\n    # only text and image, so the adapter refuses the attachment instead of\n    # dropping it. Bind that tier to a provider whose wire carries PDFs if a\n    # deployment needs it.\n    #\n    # The embed lane takes no serving preferences. text-embedding-3-large is\n    # asked for 1024 dimensions, the width every other preset stores.\n    embeddings:\n      provider: openai_compatible\n      model: openai/text-embedding-3-large\n      dimensions: 1024\n",
	"qwen3_local_vllm.yaml":        "# yaml-language-server: $schema=../margince.schema.json\n# Model setup: Qwen3 on your own server, through vLLM\n# config/presets/qwen3_local_vllm.yaml — Qwen3-14B on the operator's own box,\n# through vLLM on loopback, embeddings through a second vLLM. Zero egress.\n#\n# WHAT THIS PRESET IS NOT CERTIFIED FOR: it binds a model to every task, and the\n# certification records do not grade every one of those bindings as certified.\n# Which tasks, and how badly, is in docs/reference/ai-certification.md under\n# this file's name. Read it before binding this preset to a workspace whose\n# confidentiality decisions matter: a task graded `supported_degraded` or\n# `not_supported` answers wrongly often enough to have been measured doing so.\n#\n# No task list here on purpose. The bands move when a prompt is fixed or the\n# corpus grows, and a list in this comment would read as true long after it\n# stopped being.\n#\n# The vLLM counterpart of gemma4_local_ollama.yaml, sized for the same 24GB\n# Apple-silicon machine (vLLM with the vllm-metal plugin). Everything that\n# depends on WHICH model is served lives on the server's command line, not in\n# this file, because the vllm binding sends a plain OpenAI-wire request:\n#\n#     vllm serve mlx-community/Qwen3-14B-4bit --port 8000 \\\n#       --max-model-len 40960 --gpu-memory-utilization 0.87 \\\n#       --reasoning-parser qwen3 \\\n#       --default-chat-template-kwargs '{\"enable_thinking\": false}' \\\n#       --override-generation-config '{\"temperature\": 0.7, \"top_p\": 0.8, \"top_k\": 20}' \\\n#       --enable-prompt-tokens-details\n#     vllm serve BAAI/bge-m3 --runner pooling --port 8001 --gpu-memory-utilization 0.1\n#\n# Each flag, and what leaving it out measured, is in\n# docs/how-to/enrich-with-a-local-llm.md (\"Serve the model with vLLM instead\").\n# The two that change answers:\n# without enable_thinking=false Qwen3 thinks before every answer and a short\n# budget returns no answer at all; and this MLX build ships no sampling config,\n# so without the override vLLM samples at temperature 1.0.\n#\n# WHY QWEN3-14B. Of five models served this way on a 24GB M4 it led or tied on\n# six of seven tasks. Gemma 4 12B answers gibberish through vllm-metal, Gemma\n# 3 12B cannot hold a 40,960 window here and its JSON output loops, gpt-oss-20b\n# thinks at \"medium\" on every call because vLLM has no server-side default for\n# its effort, and both Mistral models trailed. On an NVIDIA host serve the\n# original weights instead (Qwen/Qwen3-14B) and bind that id. NOT YET\n# MEASURED: no record is committed for this binding, on either build.\n#\n# WHY THOSE MEMORY SHARES. 40,960 is the window the agent loop's prompt budget\n# needs; at it Qwen3-14B needs 6.25GiB of KV cache beside 8.3GB of weights,\n# which vLLM grants from 0.87 of the machine and not from less. bge-m3 fits in\n# the remaining 0.1. With both up about 9% of memory is left free: nothing else\n# that needs the GPU fits on a 24GB machine.\n#\n# `document_extract` cannot be served: it sends a PDF, and a vllm binding carries\n# only what its `input:` declares, which for this text-only model is nothing.\n#\n# Not loaded automatically — see README.md.\nversion: 1\n\nseeds:\n  ai_routing:\n    # sovereign is enforced, not labelled: it refuses any cloud provider, and it\n    # refuses a vllm base_url that is not loopback or a private range. Omitting\n    # base_url on the tiers resolves to http://localhost:8000, which passes.\n    profile: sovereign\n    tiers:\n      local_small: { provider: vllm, model: \"mlx-community/Qwen3-14B-4bit\" }\n      cheap_cloud: { provider: vllm, model: \"mlx-community/Qwen3-14B-4bit\" }\n      premium:     { provider: vllm, model: \"mlx-community/Qwen3-14B-4bit\" }\n      frontier:    { provider: vllm, model: \"mlx-community/Qwen3-14B-4bit\" }\n    # A second server, because vLLM serves one model per process. bge-m3 is\n    # 1024-wide, the width gemma4_local_ollama.yaml's Ollama bge-m3 has, so\n    # moving between the two presets changes no column; the vectors are still\n    # not comparable across runtimes — re-embed on any change.\n    embeddings:\n      provider: vllm\n      model: BAAI/bge-m3\n      base_url: http://localhost:8001\n      dimensions: 1024\n",
}
